content.solution_code:
class Instrument {
  constructor(name) {
    this.name = name;
  }

  play() {
    return `${this.name} is playing a sound.`;
  }
}

class Guitar extends Instrument {
  constructor(name) {
    super(name);
  }

  play() {
    return `${this.name} strums a chord.`;
  }
}

class Piano extends Instrument {
  constructor(name) {
    super(name);
  }

  play() {
    return `${this.name} plays a melody.`;
  }
}

